import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Catalogo from "../components/Catalogo";
import "../styles/dashboard.css";

export default function Dashboard(){

 const navigate = useNavigate();

 const [usuario,setUsuario] = useState(null);
 const [vista,setVista] = useState("catalogo");

 useEffect(()=>{

  const user = JSON.parse(localStorage.getItem("usuario"));

  if(!user){
   navigate("/");
  }else{
   setUsuario(user);
  }

 },[]);


 const cerrarSesion = ()=>{

  localStorage.removeItem("usuario");

  navigate("/");

 };


 return(

  <div className="dashboard-container">

   {/* MENU LATERAL */}

   <aside className="sidebar">

    <h2 className="logo">
     💎 Emerald Trade
    </h2>

    <p className="bienvenida">
     Bienvenido <br/>
     <strong>{usuario?.usuario}</strong>
    </p>


    <nav>

     <button onClick={()=>setVista("catalogo")}>
      Catálogo
     </button>

     <button onClick={()=>setVista("favoritos")}>
      Favoritos
     </button>

     <button onClick={()=>setVista("compras")}>
      Compras
     </button>

     <button onClick={()=>setVista("cuenta")}>
      Mi cuenta
     </button>

     <button onClick={()=>setVista("perfil")}>
      Editar perfil
     </button>

     <button onClick={()=>setVista("soporte")}>
      Contactar soporte
     </button>

     <button onClick={()=>setVista("faq")}>
      Preguntas frecuentes
     </button>

    </nav>


    <button
     className="logout"
     onClick={cerrarSesion}
    >
     Cerrar sesión
    </button>

   </aside>



   {/* CONTENIDO */}

   <main className="contenido">

    {vista === "catalogo" && <Catalogo />}

    {vista === "favoritos" && (
     <h2>⭐ Aquí aparecerán tus esmeraldas favoritas</h2>
    )}

    {vista === "compras" && (
     <h2>🛒 Historial de compras</h2>
    )}

    {vista === "cuenta" && (
     <h2>👤 Información de la cuenta</h2>
    )}

    {vista === "perfil" && (
     <h2>✏️ Editar perfil</h2>
    )}

    {vista === "soporte" && (
     <h2>📞 Contactar soporte</h2>
    )}

    {vista === "faq" && (
     <h2>❓ Preguntas frecuentes</h2>
    )}

   </main>

  </div>

 );

}
